/* Runs every registered check; see diffcheck.h.
 *
 *     diffcheck <manifest> [name...]
 *
 * The table of checks (diff_tests) is generated by tools/diffcheck.py.
 */
#include "diffcheck.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "arm.h"
#include "loader.h"
#include "memory.h"

typedef struct DiffTestEntry {
    const DiffTest *test;
    uint32_t size; /* the function's size, from the symbol table */
} DiffTestEntry;

extern const DiffTestEntry diff_tests[];
extern const int diff_test_count;

/* The checked function runs on a stack at the top of DTCM, as the game's own threads do. */
#define STACK_TOP 0x027e3f00u
#define STACK_SIZE 0x1000u
#define MAX_STEPS 10000000u
#define MAX_WRITES 256

typedef struct Write {
    uint32_t address;
    uint32_t size;
    uint8_t bytes[16];
} Write;

typedef struct Effects {
    uint32_t ret;
    int count;
    int overflow;
    Write writes[MAX_WRITES];
} Effects;

static void record_write(void *user, uint32_t address, const uint8_t *was, const uint8_t *now, size_t size)
{
    (void) was;
    Effects *e = user;
    /* split long runs so every record has its bytes */
    while (size > 0) {
        if (e->count == MAX_WRITES) {
            e->overflow = 1;
            return;
        }
        Write *w = &e->writes[e->count++];
        w->address = address;
        w->size = size < sizeof(w->bytes) ? (uint32_t) size : (uint32_t) sizeof(w->bytes);
        memcpy(w->bytes, now, w->size);
        address += w->size;
        now += w->size;
        size -= w->size;
    }
}

static uint32_t keep_return(const DiffTest *t, uint32_t r0)
{
    if (t->return_bits == 0) {
        return 0;
    }
    if (t->return_bits == 32) {
        return r0;
    }
    uint32_t mask = (1u << t->return_bits) - 1;
    r0 &= mask;
    if (t->return_signed && (r0 >> (t->return_bits - 1)) != 0) {
        r0 |= ~mask;
    }
    return r0;
}

/* A branch out of the checked function is a call: not part of a single-function check yet. */
typedef struct CallWatch {
    uint32_t lo, hi;
    uint32_t called;
} CallWatch;

static int stop_on_call(ArmCpu *cpu, void *user)
{
    (void) cpu;
    (void) user;
    return 1;
}

static ArmHook watch_calls(void *user, uint32_t address, void **hook_user)
{
    CallWatch *w = user;
    address &= ~1u;
    if (address >= w->lo && address < w->hi) {
        return NULL;
    }
    w->called = address;
    *hook_user = w;
    return stop_on_call;
}

static int same(const Effects *a, const Effects *b)
{
    if (a->ret != b->ret || a->count != b->count || a->overflow != b->overflow) {
        return 0;
    }
    for (int i = 0; i < a->count; i++) {
        if (a->writes[i].address != b->writes[i].address || a->writes[i].size != b->writes[i].size ||
            memcmp(a->writes[i].bytes, b->writes[i].bytes, a->writes[i].size) != 0) {
            return 0;
        }
    }
    return 1;
}

static void print_effects(const char *who, const Effects *e)
{
    printf("    %-9s returns 0x%08x, %d write(s)%s\n", who, e->ret, e->count, e->overflow ? " (more not shown)" : "");
    for (int i = 0; i < e->count && i < 8; i++) {
        printf("      %08x:", e->writes[i].address);
        for (uint32_t k = 0; k < e->writes[i].size; k++) {
            printf(" %02x", e->writes[i].bytes[k]);
        }
        printf("\n");
    }
}

static int run_test(const DiffTestEntry *entry)
{
    const DiffTest *t = entry->test;
    if (loader_load(t->module) != 0) {
        printf("%s: cannot load module %s\n", t->name, t->module);
        return 0;
    }
    MemorySnapshot *loaded = memory_snapshot();
    DiffRng rng = {0x9e3779b9u ^ t->address};
    int failures = 0;
    for (int n = 0; n < t->cases; n++) {
        memory_restore(loaded);
        uint32_t args[4] = {0, 0, 0, 0};
        t->generate(&rng, args);
        MemorySnapshot *entry_state = memory_snapshot();

        /* Reference */
        Effects ref = {0};
        ArmCpu cpu;
        arm_init(&cpu);
        memcpy(cpu.r, args, sizeof(args));
        cpu.r[13] = STACK_TOP;
        CallWatch watch = {t->address & ~1u, (t->address & ~1u) + entry->size, 0};
        if (!t->follow_calls) {
            cpu.hook_at = watch_calls;
            cpu.hook_user = &watch;
        }
        enum ArmStop stop = arm_call(&cpu, t->address, MAX_STEPS);
        if (stop != ARM_RETURNED) {
            printf("%s case %d: the reference stopped (%d) at %08x", t->name, n, (int) stop, cpu.stop_pc);
            if (stop == ARM_HOOK_STOP) {
                printf(", calling %08x", watch.called);
            }
            printf("\n");
            memory_snapshot_free(entry_state);
            failures++;
            break;
        }
        ref.ret = keep_return(t, cpu.r[0]);
        memory_diff(entry_state, STACK_TOP - STACK_SIZE, STACK_TOP, record_write, &ref);

        /* Clean */
        memory_restore(entry_state);
        Effects clean = {0};
        clean.ret = keep_return(t, t->run_clean(args));
        memory_diff(entry_state, STACK_TOP - STACK_SIZE, STACK_TOP, record_write, &clean);
        memory_snapshot_free(entry_state);

        if (!same(&ref, &clean)) {
            printf("%s case %d differs: args %08x %08x %08x %08x\n", t->name, n, args[0], args[1], args[2], args[3]);
            print_effects("reference", &ref);
            print_effects("clean", &clean);
            if (++failures >= 3) {
                break;
            }
        }
    }
    memory_restore(loaded);
    memory_snapshot_free(loaded);
    printf("%-40s %s (%d cases)\n", t->name, failures ? "DIFFERS" : "ok", t->cases);
    return failures == 0;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        fprintf(stderr, "usage: diffcheck <manifest> [name...]\n");
        return 2;
    }
    if (memory_init() != 0) {
        fprintf(stderr, "cannot reserve the DS's memory at its addresses\n");
        return 2;
    }
    if (loader_init(argv[1]) != 0) {
        return 2;
    }
    int passed = 0, run = 0;
    for (int i = 0; i < diff_test_count; i++) {
        int wanted = argc == 2;
        for (int k = 2; k < argc; k++) {
            wanted |= strcmp(argv[k], diff_tests[i].test->name) == 0;
        }
        if (wanted) {
            run++;
            passed += run_test(&diff_tests[i]);
        }
    }
    printf("\n%d of %d checks pass\n", passed, run);
    return passed == run ? 0 : 1;
}
